import bpy,numpy as np,json
from pathlib import Path
D=Path(__file__).resolve().parent;y=np.load(D/'plate-scene-linear.npy')[::-1];h,w=y.shape[:2];a=np.ones((h,w,4),np.float32);a[:,:,:3]=y;im=bpy.data.images.new('Correct linear plate',w,h,alpha=True,float_buffer=True);im.colorspace_settings.name='Linear Rec.709';im.pixels.foreach_set(a.ravel());im.update();s=bpy.context.scene;s.render.image_settings.file_format='OPEN_EXR';s.render.image_settings.color_mode='RGBA';s.render.image_settings.color_depth='32';im.save_render(str(D/'plate-scene-linear-verified.exr'),scene=s);chk=bpy.data.images.load(str(D/'plate-scene-linear-verified.exr'));chk.colorspace_settings.name='Linear Rec.709';b=np.empty(w*h*4,np.float32);chk.pixels.foreach_get(b);b=b.reshape(h,w,4)[:,:,:3];r={'mean_error':float(np.abs(b-y).mean()),'max_error':float(np.abs(b-y).max()),'roundtrip_bitwise_equal':np.array_equal(b,y)};print(r);assert r['roundtrip_bitwise_equal'];(D/'PLATE-LINEAR-STORAGE-VERIFIED.json').write_text(json.dumps(r,indent=2))
